import { Crypto, Effect, Encoding } from "effect"

export interface ArchiveEntry {
  readonly path: string
  readonly size: number
  readonly checksum: string
}

export interface ManifestFingerprint {
  readonly algorithm: "sha256"
  readonly digest: string
  readonly entryCount: number
}

export const fingerprintManifest = (
  entries: ReadonlyArray<ArchiveEntry>
): Effect.Effect<ManifestFingerprint, never, Crypto.Crypto> =>
  Effect.gen(function*() {
    const sorted = [...entries].sort((a, b) =>
      a.path < b.path ? -1 : a.path > b.path ? 1 : 0
    )
    const canonical = JSON.stringify(
      sorted.map(({ path, size, checksum }) => [path, size, checksum])
    )
    const bytes = new TextEncoder().encode(canonical)
    const crypto = yield* Crypto.Crypto
    const hash = yield* crypto.digest("SHA-256", bytes)
    const digest = Encoding.encodeHex(new Uint8Array(hash))

    return {
      algorithm: "sha256" as const,
      digest,
      entryCount: sorted.length
    }
  })
